\begin{vmatrix}
a & b & c & 0 & 0 \\
0 & a & b & c & 0 \\
0 & 0 & a & b & c \\
\alpha & b & \beta & 0 & 0 \\
0 & \alpha & b & \beta & 0 \\
\end{vmatrix}
\] which simplifies for our specific polynomials to \[
\begin{vmatrix}
1988 & b & 8891 & 0 & 0 \\
0 & 1988 & b & 8891 & 0 \\
0 & 0 & 1988 & b & 8891 \\
8891 & b & \beta & 0 & 0 \\
0 & 8891 & b & \beta & 0 \\
\end{vmatrix}
